# ============================================================ # SaúdeConectada Nordeste — Backend # Hospital Regional Santa Cruz | Petrolina-PE # # Por que Flask? # Flask é leve, direto e suficiente para um MVP hospitalar. # Não carrega complexidade desnecessária, facilitando # manutenção pela equipe técnica interna do hospital. # ============================================================ from flask import Flask, request, jsonify, send_from_directory from flask_cors import CORS from datetime import datetime import sqlite3 import re # ------------------------------------------------------------ # Configuração do app # send_from_directory serve o index.html quando o médico # abre http://localhost:5000 no navegador # ------------------------------------------------------------ app = Flask(__name__, static_folder="static") CORS(app) # Permite que o frontend acesse a API sem bloqueio de segurança DB_PATH = "prontuario.db" # ============================================================ # BANCO DE DADOS # ============================================================ def init_db(): """ Cria as tabelas no banco de dados SQLite na primeira execução. SQLite foi escolhido para o MVP por não exigir instalação separada. Em produção, migrar para PostgreSQL (prontuários) conforme especificado na arquitetura do SaúdeConectada. """ conn = sqlite3.connect(DB_PATH) cursor = conn.cursor() cursor.execute(""" CREATE TABLE IF NOT EXISTS prontuarios ( id INTEGER PRIMARY KEY AUTOINCREMENT, nome TEXT NOT NULL, -- nome do paciente cpf TEXT NOT NULL, -- identificador único do paciente nascimento TEXT NOT NULL, -- data de nascimento queixa TEXT NOT NULL, -- queixa principal (obrigatório) pressao TEXT, -- pressão arterial (ex: 120/80) temperatura REAL, -- temperatura em °C freq_cardiaca INTEGER, -- frequência cardíaca em bpm observacoes TEXT, -- observações livres do médico horario TEXT NOT NULL -- horário do atendimento (ISO 8601) ) """) conn.commit() conn.close() def get_conn(): """ Retorna uma conexão com o banco com row_factory ativado. row_factory permite acessar colunas pelo nome (ex: row['nome']) em vez de por índice (ex: row[0]) — código mais legível e seguro. """ conn = sqlite3.connect(DB_PATH) conn.row_factory = sqlite3.Row # acesso por nome de coluna return conn def row_to_dict(row): """ Converte uma linha do banco (sqlite3.Row) em dicionário Python, o que permite serializar para JSON com jsonify(). """ return dict(row) # ============================================================ # VALIDAÇÕES # ============================================================ def validar_cpf_formato(cpf): """ Valida o formato do CPF: aceita '000.000.000-00' ou '00000000000'. Não valida o dígito verificador (pode ser adicionado futuramente). Por que validar o CPF? O CPF é o identificador do paciente. CPFs mal formatados podem gerar duplicatas ou impedir a busca de histórico correto. """ cpf_limpo = re.sub(r'\D', '', cpf) # remove tudo que não é dígito return len(cpf_limpo) == 11 def normalizar_cpf(cpf): """ Remove pontuação do CPF e retorna só os 11 dígitos. Isso padroniza o armazenamento e facilita a busca. Ex: '123.456.789-09' → '12345678909' """ return re.sub(r'\D', '', cpf) def validar_campos_obrigatorios(dados, campos): """ Verifica se todos os campos obrigatórios estão presentes e não vazios. Retorna None se tudo OK, ou uma mensagem de erro se falta algo. Por que centralizar a validação? Evita repetir a mesma lógica em cada rota — princípio DRY (Don't Repeat Yourself). """ for campo in campos: if not dados.get(campo) or str(dados[campo]).strip() == "": return f"Campo obrigatório ausente ou vazio: '{campo}'" return None # ============================================================ # ROTAS # ============================================================ # ------------------------------------------------------------ # POST /prontuario # Recebe e armazena os dados de um novo atendimento. # # Por que POST e não GET? # POST envia dados no corpo da requisição (invisível na URL), # adequado para dados sensíveis de saúde (LGPD Art. 11). # ------------------------------------------------------------ @app.route("/prontuario", methods=["POST"]) def criar_prontuario(): # Lê o JSON enviado pelo frontend dados = request.get_json() # Verifica se o corpo da requisição é um JSON válido if not dados: return jsonify({ "erro": "Corpo da requisição inválido. Envie um JSON." }), 400 # 400 Bad Request — dado inválido enviado pelo cliente # Valida campos obrigatórios conforme especificado no case campos_obrigatorios = ["nome", "cpf", "nascimento", "queixa"] erro = validar_campos_obrigatorios(dados, campos_obrigatorios) if erro: return jsonify({"erro": erro}), 400 # Valida formato do CPF antes de salvar if not validar_cpf_formato(dados["cpf"]): return jsonify({ "erro": "CPF inválido. Use o formato 000.000.000-00 ou 11 dígitos." }), 400 # Valida temperatura se informada (valor clinicamente plausível) if dados.get("temperatura"): try: temp = float(dados["temperatura"]) if not (30.0 <= temp <= 45.0): return jsonify({ "erro": "Temperatura fora do intervalo plausível (30°C–45°C)." }), 400 except ValueError: return jsonify({"erro": "Temperatura deve ser um número."}), 400 # Valida frequência cardíaca se informada if dados.get("freq_cardiaca"): try: fc = int(dados["freq_cardiaca"]) if not (20 <= fc <= 300): return jsonify({ "erro": "Frequência cardíaca fora do intervalo plausível (20–300 bpm)." }), 400 except ValueError: return jsonify({"erro": "Frequência cardíaca deve ser um número inteiro."}), 400 # Normaliza o CPF para armazenar sempre sem pontuação cpf_normalizado = normalizar_cpf(dados["cpf"]) # Registra o horário do atendimento automaticamente no servidor # Por que no servidor e não no cliente? # Garante consistência mesmo se o relógio do computador do médico estiver errado horario = datetime.now().strftime("%Y-%m-%dT%H:%M:%S") conn = get_conn() cursor = conn.cursor() cursor.execute(""" INSERT INTO prontuarios (nome, cpf, nascimento, queixa, pressao, temperatura, freq_cardiaca, observacoes, horario) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?) """, ( dados["nome"].strip(), cpf_normalizado, dados["nascimento"], dados["queixa"].strip(), dados.get("pressao", ""), dados.get("temperatura"), dados.get("freq_cardiaca"), dados.get("observacoes", "").strip(), horario, )) conn.commit() novo_id = cursor.lastrowid conn.close() # 201 Created — recurso criado com sucesso return jsonify({ "mensagem": "Atendimento registrado com sucesso.", "id": novo_id, "horario": horario }), 201 # ------------------------------------------------------------ # GET /prontuarios # Retorna todos os atendimentos registrados. # Usado pela tela de listagem geral de atendimentos. # ------------------------------------------------------------ @app.route("/prontuarios", methods=["GET"]) def listar_prontuarios(): conn = get_conn() cursor = conn.cursor() # Ordena do mais recente para o mais antigo # Por que DESC? Médicos precisam ver os casos mais recentes primeiro cursor.execute("SELECT * FROM prontuarios ORDER BY horario DESC") registros = [row_to_dict(row) for row in cursor.fetchall()] conn.close() # 200 OK — requisição bem-sucedida return jsonify(registros), 200 # ------------------------------------------------------------ # GET /prontuarios/<cpf> # Retorna o histórico completo de um paciente pelo CPF. # Essencial para médicos plantonistas que precisam consultar # o histórico rápido de um paciente na triagem. # ------------------------------------------------------------ @app.route("/prontuarios/<cpf>", methods=["GET"]) def historico_paciente(cpf): # Normaliza o CPF recebido na URL para buscar sem pontuação cpf_normalizado = normalizar_cpf(cpf) # Valida o formato antes de consultar o banco if len(cpf_normalizado) != 11: return jsonify({ "erro": "CPF inválido. Informe 11 dígitos ou no formato 000.000.000-00." }), 400 conn = get_conn() cursor = conn.cursor() cursor.execute( "SELECT * FROM prontuarios WHERE cpf = ? ORDER BY horario DESC", (cpf_normalizado,) ) registros = [row_to_dict(row) for row in cursor.fetchall()] conn.close() # 404 Not Found — paciente não encontrado no sistema if not registros: return jsonify({ "erro": "Nenhum atendimento encontrado para este CPF.", "cpf": cpf_normalizado }), 404 # Retorna também o nome do paciente para exibir no cabeçalho da tela return jsonify({ "paciente": registros[0]["nome"], "cpf": cpf_normalizado, "total_atendimentos": len(registros), "atendimentos": registros }), 200 # ------------------------------------------------------------ # Serve o frontend (index.html) # Quando o médico abre http://localhost:5000, recebe o HTML # ------------------------------------------------------------ @app.route("/") def index(): return send_from_directory("static", "index.html") # ============================================================ # PONTO DE ENTRADA # ============================================================ if __name__ == "__main__": init_db() print("=" * 50) print(" SaúdeConectada Nordeste — Backend iniciado") print(" Hospital Regional Santa Cruz | Petrolina-PE") print("=" * 50) print(" Acesse: http://localhost:5000") print(" Rotas disponíveis:") print(" POST /prontuario → novo atendimento") print(" GET /prontuarios → todos os atendimentos") print(" GET /prontuarios/<cpf> → histórico do paciente") print("=" * 50) # debug=True
